const storedMessages = localStorage.getItem('app_messages');
const messages = ref(storedMessages ? JSON.parse(storedMessages) : initialMessages);

const syncStorage = () => {
  localStorage.setItem('app_messages', JSON.stringify(messages.value));
};

export function useMessages() {
  const addMessage = (newMessage) => {
    messages.value.push({ id: messages.value.length + 1, ...newMessage });
    syncStorage();
  };

  const getMessagesByChatId = (id) => {
    return messages.value.filter((message) => message.chatId === Number(id));
  };

  return {
    messages,
    addMessage,
    getMessagesByChatId,
  };
}
